#!/usr/bin/env python3
"""Generate real file/line links for the frozen protocol, then attach reviewed explanations."""
import re,subprocess
from pathlib import Path
r=Path(__file__).resolve().parents[1];sha=(r/"evidence/audited-source.sha").read_text().strip()
out=r/"docs/code-walkthrough";out.mkdir(parents=True,exist_ok=True)
topics={
"deposit":("Lender enters the market","Checkpoint interest before pricing ownership. Use tracked cash plus aggregate debt, never the raw token balance. A first depositor receives six extra share decimals; later deposits round shares down. Enforce cap and minShares, then add cash and mint before the exact token pull. A failed pull reverts the entire mint. Balance-derived pricing or mint-before-accrual can transfer old lenders' value to new entrants. Alternatives: ERC-4626 virtual offsets; this market instead excludes donations.","testDonationCannotInflatePrice / testDepositWithdrawRedeem"),
"withdraw":("Exact-asset lender exit","Round the share burn UP so a withdrawing lender cannot underpay remaining owners. Require idle cash and maxShares, then prevent a final rounded burn from stranding receivables (L-01). Burn and reduce recognized cash before the transfer. Available receivables are not available cash. If all assets cannot be paid, redeeming the entire claim must wait for repayment/loss settlement.","testRegression_LastShareCannotOrphanReceivables / testInsufficientLiquidity"),
"redeem":("Exact-share lender exit","Round asset proceeds DOWN. Cash can be insufficient even when the claim has positive book value. Burn shares and reduce cash before interacting with the token. Zero proceeds are allowed so all owners can discard worthless shares after total loss. With S=0 there must be no prior lender claim; only then may a market restart.","testDustLiquidationAndRestart / testRedeemBlockedUntilBorrowerRepays"),
"addCollateral":("Borrower reduces risk","Record collateral balances and aggregate custody, then pull the exact amount. A price read is unnecessary: adding genuine collateral cannot increase debt. Amount caps and supported-token assumptions still apply. No third party may redirect the caller's collateral account.","testOracleFailureAllowsRepaymentAndCollateralTopup"),
"removeCollateral":("Borrower increases risk","Accrue debt, tentatively reduce collateral and check origination LTV if debt remains. The transaction rolls back when the residual position is unsafe. Debt-free collateral release needs no oracle. Pay the caller only after accounting/health checks; shared locking prevents cross-function callback escape.","testBorrowLTVAndWithdrawCollateralChecks"),
"borrow":("Cash becomes a receivable","Mint ceil(assets*RAY/index) debt shares, reduce cash, then validate the caller's conservative rounded liability using a fresh independent price. Only then transfer the exact loan amount. The debt addition cannot dilute pre-existing lender receivables. After price shocks or interest, health may later deteriorate: the LTV check is an execution-time constraint.","testBorrowAtLTVBoundary / testFuzz_BorrowRepayRounding"),
"repay":("Receivable becomes cash","Accept exact debt shares and collect ceil(shares*index/RAY), respecting maxAssets. Burn debt shares, add cash, then pull funds. Anyone may pay another borrower's debt, but cannot redirect their collateral. Aggregate receivable reduction can be one raw unit smaller than individual rounded payment; that difference is lender rounding surplus, not bad debt.","testThirdPartyRepayment / testPartialRepaymentRoundsUp"),
"liquidate":("Unhealthy collateral settlement","Read independent price; require debt above the 80% threshold. Calculate collateral-affordable repayment after the 5% bonus. Partial repayment seizes collateral down; collateral-exhausting settlement caps repayment and seizes the remainder. Remove residual debt shares and measure the EXACT aggregate receivable write-off, reducing lender share value. Payment and seizure are atomic; an unfunded caller cannot persist the write-off. No insurance magic can eliminate losses after a price gap.","testGapLossSocialization / testUnfundedLiquidationCannotCommitLosses"),
"_previewIndex":("Lazy time-value accounting","Compute utilization from stored receivables/cash, apply the piecewise nominal APR for elapsed seconds, and cap the index. Use integer mulDiv with explicit RAY/WAD units. Views preview the same accrual that the next mutation checkpoints. Frequent checkpoints compound: APR must not be mislabeled APY. The index ceiling avoids indefinite numeric growth at the cost of eventual interest cessation.","testFuzz_ActualAccrual / testInterestIndexCapAndIdleAccrual"),
"_accrue":("Materialize the lazy index","Measure old aggregate receivables, materialize the preview index and timestamp, and emit actual added interest. No borrower loop is needed. Monetary accounting must separately include this interest and the rounding surplus of repayments when comparing states across mined blocks.","testInterestAndFullRepayment / local-smoke evidence"),
"_value":("Unit-safe valuation","Compute floor(collateralRaw*priceWAD*assetUnit/(collateralUnit*WAD)) in one mulDiv. The normalized price is loan human units per collateral human unit. Conservative flooring prevents overstating collateral. Decimal metadata is fixed at deployment and limited to 18. A 6-decimal loan with 18-decimal collateral is the principal test fixture.","testBorrowAtLTVBoundary / MainnetForkTest"),
"_price":("Oracle trust boundary","Reject zero or excessive normalized prices even if a custom immutable oracle supplies them. FeedOracle adds staleness/round/sequencer policy. This boundary does not validate whether the deployer chose the correct economic feeds; feed selection remains a deployment trust assumption.","testInvalidOracleBounds / FeedOracleTest"),
"_pull":("Exact incoming asset transfer","Record vault token balance, use SafeERC20.transferFrom, then require an exact increment. SafeERC20 supports optional-return USDT semantics. Fee-on-transfer/rebasing/lying token behavior is outside the support model; do not silently mint claims against missing funds.","testNoReturnUSDTStyleToken / testFeeOnTransferIncomingRejected"),
"_push":("Exact outgoing asset transfer","Require exact vault debit AND exact recipient credit after SafeERC20.transfer. A receiver-side fee cannot silently charge the withdrawing user. Every caller is nonReentrant. A token callback that donates funds may cause this strict check to revert, but cannot commit a partially paid withdrawal.","testOutgoingFeeAndFalseReturnRejected / testMutationAndReadOnlyReentrancyRejected"),
"_backed":("Custody sanity check","Actual balances must cover tracked loan cash and aggregate collateral. Surplus donations are ignored for claim pricing. A negative rebase fails closed; this implementation has no administrator to manufacture accounting recovery.","testNegativeRebaseDetected / invariant_PhysicalBacking"),
"totalAssets":("Valuation API","Return tracked cash plus ceiling-rounded aggregate debt at the preview index. stableView refuses valuation while a mutating token interaction is in progress. An integration should use this guarded valuation API, not recompute an exchange rate from raw public getters during callbacks.","testMutationAndReadOnlyReentrancyRejected / invariant_AssetReceivableIdentity"),
"healthFactor":("Liquidation eligibility view","Return threshold-adjusted collateral/debt scaled by WAD. Debt-free positions return the maximum integer without requesting a price. A factor below 1e18 indicates liquidation eligibility, not an assurance that a liquidator or external liquidity exists.","testDebtFreeHealthAndBaseRate / testPartialAndFullLiquidation")
}
lines=(r/"src/LendingVault.sol").read_text().splitlines()
text=f"# LendingVault source walkthrough\n\nFrozen source commit: {sha}. All paths/line links below are generated from the actual source.\n\n"
for name,(title,explanation,tests) in topics.items():
    line=next(i for i,x in enumerate(lines,1) if re.search(r"function\s+"+re.escape(name)+r"\s*\(",x))
    text+=f"## {name}: {title}\n\n[Source line {line}](../../src/LendingVault.sol#L{line})\n\n{explanation}\n\nTests/evidence: {tests}. Runtime commands: forge test --match-contract LendingVaultTest -vv; forge test --match-contract LendingInvariant -vv. See [measured results](../testing/results.md), not hypothetical sample output.\n\n"
text+="## Execution order and debugging\n\nTrace a normal position with forge test --match-test testInterestAndFullRepayment -vvvv. Identify the external token calls, state writes, Accrue event, debt-share burn and final share burn. Trace the vulnerable version through the separate worktree command in finding L-01; do not overwrite the fixed checkout. Use forge test --debug --match-test testPartialAndFullLiquidation for the local debugger. A trace is evidence of this execution, not all possible executions.\n"
(out/"LendingVault.md").write_text(text)
(out/"README.md").write_text(f"# Source walkthrough\n\nCommit {sha}.\n\n- [Vault: state, formulas, security and tests](LendingVault.md)\n- [Oracle and interest model](oracle-and-rates.md)\n- [Learning exercises and defense](../learning/interview-defense.md)\n- [Full source](../../src/LendingVault.sol)\n\nOpenZeppelin implements ERC20 mechanics, safe calls, full-precision arithmetic and the storage reentrancy lock. The custom protocol code composes these components; it does not claim to reinvent them.\n")
